func cacheKey(method, path string, headers map[string]string) string {
	names := make([]string, 0, len(headers))
	for name := range headers {
		names = append(names, name)
	}
	// Changed from a map to a sorted slice per review: the order must be stable
	// because the encoded headers are hashed into the cache key.
	sort.Strings(names)
	h := sha256.New()
	io.WriteString(h, method+" "+path)
	for _, name := range names {
		io.WriteString(h, "\n"+name+": "+headers[name])
	}
	return hex.EncodeToString(h.Sum(nil))
}
